INSERT INTO roles(name) VALUES('PILOT_OWNER') ON CONFLICT DO NOTHING;
CREATE TABLE pilot_rollout_policy(id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(id),enforcement_required BOOLEAN NOT NULL DEFAULT FALSE);
INSERT INTO pilot_rollout_policy(id) VALUES(TRUE);
CREATE TABLE pilot_assessments(id UUID PRIMARY KEY DEFAULT uuidv7(),service TEXT NOT NULL CHECK(service IN('COMMUNITY','WELLBEING_EDUCATION','LISTENERS','PROFESSIONAL_BOOKING','CLINICAL_TEXT','CLINICAL_MEDIA','REAL_PAYMENTS','CLINICAL_RECORDS')),country_code CHAR(2) NOT NULL REFERENCES geography_countries(code),source_commit CHAR(40) NOT NULL,notice_version INTEGER,notice_sha256 CHAR(64),revision BIGINT NOT NULL DEFAULT 1,created_by UUID NOT NULL REFERENCES users(id),created_session UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX pilot_service_current ON pilot_assessments(service,country_code,created_at DESC,id DESC);
CREATE TABLE pilot_evidence(id UUID PRIMARY KEY DEFAULT uuidv7(),assessment_id UUID NOT NULL REFERENCES pilot_assessments(id),criterion TEXT NOT NULL CHECK(criterion IN('SOURCE','CI','SECURITY','PRIVACY','LEGAL','STAFFING','PROVIDERS','MONITORING','BACKUP_RESTORE','INCIDENT_RESPONSE','DEVICES','CAPACITY','ROLLBACK')),state TEXT NOT NULL CHECK(state IN('PASS','FAIL','BLOCKED','APPROVAL_REQUIRED','DEVICE_TEST_REQUIRED')),kind TEXT NOT NULL,reference TEXT NOT NULL,artifact_sha256 CHAR(64) NOT NULL,exact_tests JSONB NOT NULL,responsible_role TEXT NOT NULL,risks JSONB NOT NULL,author_id UUID NOT NULL REFERENCES users(id),author_session UUID NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX pilot_evidence_latest ON pilot_evidence(assessment_id,criterion,created_at DESC,id DESC);
CREATE TABLE pilot_evidence_reviews(evidence_id UUID PRIMARY KEY REFERENCES pilot_evidence(id),reviewer_id UUID NOT NULL REFERENCES users(id),review_session UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pilot_owner_approvals(id UUID PRIMARY KEY DEFAULT uuidv7(),assessment_id UUID NOT NULL REFERENCES pilot_assessments(id),assessment_revision BIGINT NOT NULL,owner_id UUID NOT NULL REFERENCES users(id),owner_session UUID NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(assessment_id,assessment_revision));
CREATE TABLE pilot_assessment_revocations(assessment_id UUID PRIMARY KEY REFERENCES pilot_assessments(id),reason TEXT NOT NULL CHECK(reason IN('AUTHORITY_CHANGED','EXPLICIT_STOP')),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pilot_participants(id UUID PRIMARY KEY DEFAULT uuidv7(),assessment_id UUID NOT NULL REFERENCES pilot_assessments(id),user_id UUID NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'INVITED' CHECK(state IN('INVITED','ACCEPTED','OPTED_OUT','REVOKED')),revision BIGINT NOT NULL DEFAULT 1,notice_version INTEGER NOT NULL,notice_sha256 CHAR(64) NOT NULL,invited_by UUID NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(assessment_id,user_id));
CREATE INDEX pilot_own_participation ON pilot_participants(user_id,state,expires_at);
CREATE TABLE pilot_participant_events(id UUID PRIMARY KEY DEFAULT uuidv7(),participant_id UUID NOT NULL REFERENCES pilot_participants(id),actor_id UUID NOT NULL REFERENCES users(id),state TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE FUNCTION pilot_revoke_authority() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO pilot_assessment_revocations(assessment_id,reason)
 SELECT a.id,'AUTHORITY_CHANGED' FROM pilot_assessments a WHERE OLD.role_id IN(SELECT id FROM roles WHERE name IN('TRUST_PLATFORM','PILOT_OWNER')) AND (a.created_by=OLD.user_id OR EXISTS(SELECT 1 FROM pilot_evidence e LEFT JOIN pilot_evidence_reviews v ON v.evidence_id=e.id WHERE e.assessment_id=a.id AND (e.author_id=OLD.user_id OR v.reviewer_id=OLD.user_id)) OR EXISTS(SELECT 1 FROM pilot_owner_approvals o WHERE o.assessment_id=a.id AND o.owner_id=OLD.user_id)) ON CONFLICT DO NOTHING;
 RETURN OLD;END $$;
CREATE TRIGGER pilot_authority_removed AFTER DELETE ON user_roles FOR EACH ROW EXECUTE FUNCTION pilot_revoke_authority();
CREATE FUNCTION pilot_restrict_account() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.status<>'ACTIVE' OR NOT NEW.email_verified OR NEW.deleted_at IS NOT NULL THEN
 INSERT INTO pilot_assessment_revocations(assessment_id,reason) SELECT a.id,'AUTHORITY_CHANGED' FROM pilot_assessments a WHERE a.created_by=NEW.id OR EXISTS(SELECT 1 FROM pilot_evidence e LEFT JOIN pilot_evidence_reviews v ON v.evidence_id=e.id WHERE e.assessment_id=a.id AND(e.author_id=NEW.id OR v.reviewer_id=NEW.id)) OR EXISTS(SELECT 1 FROM pilot_owner_approvals o WHERE o.assessment_id=a.id AND o.owner_id=NEW.id) ON CONFLICT DO NOTHING;END IF;RETURN NEW;END $$;
CREATE TRIGGER pilot_account_restricted AFTER UPDATE OF status,email_verified,deleted_at ON users FOR EACH ROW EXECUTE FUNCTION pilot_restrict_account();
DO $$ DECLARE tab TEXT;BEGIN FOREACH tab IN ARRAY ARRAY['pilot_evidence','pilot_evidence_reviews','pilot_owner_approvals','pilot_assessment_revocations','pilot_participant_events'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION clinic_append_only()',tab||'_immutable',tab);END LOOP;END $$;
INSERT INTO policy_documents(policy_key,version,title,summary,content,status) VALUES('pilot-participation',1,'Controlled pilot participation — review required','Draft; not an approved invitation or legal notice.','DRAFT FOR INDEPENDENT REVIEW. Participation is optional and service-specific. Availability depends on current authorization and human coverage. Listeners provide nonclinical peer support; GreenOcean is not an emergency service. Leaving stops new pilot participation; existing records,account rights and financial/care obligations have separate controls. Use support or report routes. Actual scope,hours,contacts,privacy and legal wording require approval before publication.','DRAFT') ON CONFLICT DO NOTHING;
